<div class='page-header mb-3'><h2 class='page-title'>الموظفون</h2></div><div class='row'><div class='col-lg-8'><div class='card'><table class='table'><thead><tr><th>الكود</th><th>الاسم</th><th>الهاتف</th><th>البريد</th><th>الحالة</th></tr></thead><tbody><?php foreach($employees as$e):?><tr><td><?=e($e['employee_code'])?></td><td><?=e($e['name'])?></td><td><?=e($e['phone']??'—')?></td><td><?=e($e['email']??'—')?></td><td><?=$e['is_active']?'نشط':'غير نشط'?></td></tr><?php endforeach;?></tbody></table></div></div><div class='col-lg-4'><form class='card' method='post' action='/employees'><div class='card-header'>إضافة موظف</div><div class='card-body'><input type='hidden' name='_token' value='<?=e($csrfToken)?>'><label class='form-label'>الاسم<input class='form-control' name='name' required></label><label class='form-label'>الهاتف<input class='form-control' name='phone'></label><label class='form-label'>البريد الإلكتروني<input class='form-control' type='email' name='email'></label><label class='form-check'><input class='form-check-input' type='checkbox' name='is_active' checked><span class='form-check-label'>نشط</span></label></div><div class='card-footer'><button class='btn btn-primary'>حفظ</button></div></form></div></div>
